#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    int minSetSize(std::vector<int>& arr) {
        std::unordered_map<int, int> counts;
        for (int x : arr) counts[x]++;
        std::vector<int> freqs;
        for (auto& [_, c] : counts) freqs.push_back(c);
        std::sort(freqs.rbegin(), freqs.rend());
        int removed = 0, needed = (arr.size() + 1) / 2, ans = 0;
        for (int f : freqs) {
            removed += f;
            ans++;
            if (removed >= needed) break;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int minSetSize(int[] arr) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int x : arr) counts.put(x, counts.getOrDefault(x, 0) + 1);
        List<Integer> freqs = new ArrayList<>(counts.values());
        freqs.sort(Collections.reverseOrder());
        int removed = 0, needed = (arr.length + 1) / 2, ans = 0;
        for (int f : freqs) {
            removed += f;
            ans++;
            if (removed >= needed) break;
        }
        return ans;
    }
}

var minSetSize = function(arr) {
    const counts = new Map();
    for (const x of arr) counts.set(x, (counts.get(x) || 0) + 1);
    const freqs = Array.from(counts.values()).sort((a, b) => b - a);
    let removed = 0, needed = Math.ceil(arr.length / 2), ans = 0;
    for (const f of freqs) {
        removed += f;
        ans++;
        if (removed >= needed) break;
    }
    return ans;
};
